func factorize(n uint64) [][2]uint64 {
	factors := make([][2]uint64, 0)
	for p := uint64(2); p*p <= n; p++ {
		if n%p != 0 {
			continue
		}
		var exponent uint64
		for n%p == 0 {
			n /= p
			exponent++
		}
		factors = append(factors, [2]uint64{p, exponent})
	}
	if n > 1 {
		factors = append(factors, [2]uint64{n, 1})
	}
	return factors
}

