	divisors := []uint64{1}
	for _, f := range factors {
		oldLength := len(divisors)
		value := uint64(1)
		for e := uint64(1); e <= f[1]; e++ {
			value *= f[0]
			for i := 0; i < oldLength; i++ {
				divisors = append(divisors, divisors[i]*value)
			}
		}
	}
	return divisors
}

