		p := uint64(pi)
		term, sum := uint64(1), uint64(1)

		for exponent := 1; ; exponent++ {
			if term > (A-sum)/p {
				break
			}
			term *= p
			sum += term

			if exponent >= 2 && A%sum == 0 {
				candidates = append(candidates, Candidate{p: p, d: sum})
			}
		}
	}

	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].p != candidates[j].p {
			return candidates[i].p < candidates[j].p
		}
		return candidates[i].d < candidates[j].d
	})

