	memo       = make(map[state]int64)
	repCache   = make(map[int64][]int64)
	primeCache = make(map[int64]bool)
)

func buildPrimes(limit int) {
	composite := make([]bool, limit+1)
	for i := 2; i <= limit; i++ {
		if !composite[i] {
			primes = append(primes, i)
			if i <= limit/i {
