		return result
	}

	result := make([]int64, 0)

	if value >= 3 {
		p := value - 1
		if isPrime(p) {
			result = append(result, p)
		}
	}

	minSum := int64(7) // 1 + 2 + 2^2
	for exponent := 2; minSum <= value; exponent++ {
		estimate := int64(math.Pow(float64(value), 1.0/float64(exponent)))
		start := estimate - 4
		if start < 2 {
			start = 2
		}

		for p := start; p <= estimate+4; p++ {
			if geometricSumEquals(p, exponent, value) && isPrime(p) {
				result = append(result, p)
			}
		}

		minSum = minSum*2 + 1
	}

	repCache[value] = result
	return result
}

func divisors(n int64) []int64 {
	type factor struct {
		prime int64
		power int
	}

	factors := make([]factor, 0)
	remaining := n

	for _, pi := range primes {
		p := int64(pi)
		if p > remaining/p {
			break
		}
		if remaining%p == 0 {
			count := 0
			for remaining%p == 0 {
				remaining /= p
				count++
			}
			factors = append(factors, factor{p, count})
		}
	}

	if remaining > 1 {
		factors = append(factors, factor{remaining, 1})
	}

	result := []int64{1}
	for _, f := range factors {
		currentLength := len(result)
		multiplier := int64(1)
		for e := 1; e <= f.power; e++ {
			multiplier *= f.prime
			for i := 0; i < currentLength; i++ {
				result = append(result, result[i]*multiplier)
			}
		}
	}

	return result
}

func solve(remaining, minPrime int64) int64 {
	if remaining == 1 {
		return 1
	}

	key := state{remaining, minPrime}
	if result, ok := memo[key]; ok {
		return result
	}

	var answer int64
	for _, divisor := range divisors(remaining) {
		if divisor == 1 {
			continue
		}
		for _, p := range representations(divisor) {
			if p >= minPrime {
				answer += solve(remaining/divisor, p+1)
			}
		}
	}

	memo[key] = answer
	return answer
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var a int64
	fmt.Fscan(in, &a)

	buildPrimes(1_000_000)
	fmt.Fprintln(out, solve(a, 2))
}
